 public static readonly HashSet<string> Ids=new HashSet<string>(new[]{"bones","bonepile","skullpile","statue","statue_seated","statue_damaged","stele","gravestone","brokencol","brokencol_base","columnfragment","lantern","miningtools","supplycrate","smallbarrel","tiedsack","coiledrope","storagepot","brokenpot"});
