 static void Check(bool ok,string why){if(!ok)throw new InvalidDataException("Small props: "+why);}
 static bool Finite(float f){return !float.IsNaN(f)&&!float.IsInfinity(f);}
 static void Floats(float[] a,int n){Check(a!=null&&a.Length==n,"array length");foreach(float f in a)Check(Finite(f),"nonfinite value");}
 static Vector3 V(float[] a){Floats(a,3);return new Vector3(a[0],a[1],a[2]);}
 static float Number(string s){float f=float.Parse(s,CultureInfo.InvariantCulture);Check(Finite(f),"CSV nonfinite");return f;}
 public static Data Read(string file){var d=JsonUtility.FromJson<Data>(File.ReadAllText(file));
 if(d!=null&&!string.IsNullOrEmpty(d.library)){Check(d.library=="small_props_library.json"&&d.assets==null,"library reference");var lib=JsonUtility.FromJson<Data>(SharedAssetFiles.ReadText(SharedAssetFiles.Resolve(Path.GetDirectoryName(file),d.library)));Check(lib!=null&&lib.version==d.version&&lib.units==d.units&&lib.axes==d.axes,"library version");d.chestSurfacesV1=lib.chestSurfacesV1;d.assets=lib.assets;d.additionalAssets=lib.additionalAssets;d.extraNativeAssetsV1=lib.extraNativeAssetsV1;d.extraNativeAssetsV2=lib.extraNativeAssetsV2;d.extraNativeAssetsV3=lib.extraNativeAssetsV3;d.extraNativeAssetsV4=lib.extraNativeAssetsV4;d.chestOrnamentsV1=lib.chestOrnamentsV1;d.chestEffectsV1=lib.chestEffectsV1;d.chestEffectsV2=lib.chestEffectsV2;d.rowboatAsset=lib.rowboatAsset;d.atlas=lib.atlas;}
 Check(d!=null&&d.version==1&&d.units=="metres"&&d.axes=="Unity X/Y/Z"&&d.assets!=null&&d.assets.Length==Ids.Count,"format/count");if(d.additionalAssets!=null){var extra=new HashSet<string>();foreach(var a in d.additionalAssets)Check(a!=null&&AdditionalIds.Contains(a.id)&&extra.Add(a.id),"additional identity");var combined=new List<Asset>(d.assets);combined.AddRange(d.additionalAssets);d.assets=combined.ToArray();}if(d.rowboatAsset!=null&&!string.IsNullOrEmpty(d.rowboatAsset.id)){Check(d.rowboatAsset.id=="rowboat","optional rowboat identity");var list=new List<Asset>(d.assets);list.Add(d.rowboatAsset);d.assets=list.ToArray();}if(d.extraNativeAssetsV1!=null){var extra=new HashSet<string>();var list=new List<Asset>(d.assets);foreach(var a in d.extraNativeAssetsV1){Check(a!=null&&ExtraIds.Contains(a.id)&&extra.Add(a.id),"extra native identity");list.Add(a);}d.assets=list.ToArray();}if(d.extraNativeAssetsV2!=null){var extra=new HashSet<string>();var list=new List<Asset>(d.assets);foreach(var a in d.extraNativeAssetsV2){Check(a!=null&&ExtraV2Ids.Contains(a.id)&&extra.Add(a.id),"extra native identity");list.Add(a);}d.assets=list.ToArray();}if(d.extraNativeAssetsV3!=null){var extra=new HashSet<string>();var list=new List<Asset>(d.assets);foreach(var a in d.extraNativeAssetsV3){Check(a!=null&&ExtraV3Ids.Contains(a.id)&&extra.Add(a.id),"extra native identity");list.Add(a);}d.assets=list.ToArray();}if(d.extraNativeAssetsV4!=null){var extra=new HashSet<string>();var list=new List<Asset>(d.assets);foreach(var a in d.extraNativeAssetsV4){Check(a!=null&&ExtraV4Ids.Contains(a.id)&&extra.Add(a.id),"chest series identity");list.Add(a);}d.assets=list.ToArray();}var found=new HashSet<string>();var surfaces=new Dictionary<string,string>();foreach(var a in d.assets){Check(a!=null&&(Ids.Contains(a.id)||AdditionalIds.Contains(a.id)||ExtraIds.Contains(a.id)||ExtraV2Ids.Contains(a.id)||ExtraV3Ids.Contains(a.id)||ExtraV4Ids.Contains(a.id))&&found.Add(a.id)&&a.assetKey=="tdj/"+a.id&&a.source=="editor-procedural-mesh","identity");Check(a.positions!=null&&a.positions.Length>0&&a.positions.Length%3==0&&a.positions.Length<180000,"mesh count");int n=a.positions.Length/3;Floats(a.positions,n*3);Floats(a.normals,n*3);Floats(a.colors,n*3);Floats(a.glow,n);Floats(a.uv,n*2);Check(a.triangles!=null&&a.triangles.Length%3==0,"triangles");foreach(int ix in a.triangles)Check(ix>=0&&ix<n,"index");Check(Finite(a.radius)&&a.radius>=0&&Finite(a.height)&&a.height>0,"collision metadata");Check(a.material=="default"||a.material=="stone"||a.material=="carved"||a.material=="cards2"||a.material=="snow"||(a.material=="chestmetal"&&ExtraV4Ids.Contains(a.id)&&(a.id=="treasurechest_silver"||a.id=="treasurechest_gold"||a.id=="treasurechest_rainbow")),"material");foreach(float g in a.glow)Check(g>=0&&g<=4,"glow");if(a.surface!=null&&string.IsNullOrEmpty(a.surface.id)&&a.surface.width==0&&a.surface.height==0&&string.IsNullOrEmpty(a.surface.png))a.surface=null;if(a.surface!=null){var q=a.surface;Check((((a.id=="crossgrave"||a.id=="gravestone")&&q.id=="grave-stone-grain-v1"&&q.width==128&&q.height==128&&q.wrap=="repeat")||(a.id=="seafan"&&q.id=="seafan-net-v1"&&q.width==256&&q.height==256&&q.wrap=="clamp"))&&q.colorSpace=="sRGB"&&q.filter=="trilinear"&&q.mipmaps&&!string.IsNullOrEmpty(q.png)&&q.png.Length<200000,"optional surface contract "+a.id+" id="+q.id+" size="+q.width+"x"+q.height+" color="+q.colorSpace+" filter="+q.filter+" wrap="+q.wrap+" mips="+q.mipmaps+" pngLength="+(q.png==null?0:q.png.Length));Check(!surfaces.ContainsKey(q.id)||surfaces[q.id]==q.png,"surface identity conflict");surfaces[q.id]=q.png;}if(a.circleColliders!=null){Check(AdditionalIds.Contains(a.id)&&!a.shape&&a.radius>0&&a.circleColliders.Length>0,"circle proxy format");foreach(var q in a.circleColliders){Floats(q.center,3);Check(Finite(q.radius)&&Finite(q.height)&&Mathf.Abs(q.radius-a.radius)<.000001f&&Mathf.Abs(q.height-a.height)<.000001f,"circle proxy metadata");}}if(a.pointLight!=null&&string.IsNullOrEmpty(a.pointLight.mode)&&a.pointLight.color==0&&a.pointLight.intensity==0&&a.pointLight.height==0&&a.pointLight.range==0&&a.pointLight.decay==0)a.pointLight=null;if(a.pointLight!=null){var q=a.pointLight;Check(AdditionalIds.Contains(a.id)&&q.mode=="uniform-height-from-ground"&&q.color>=0&&q.color<=0xffffff&&Finite(q.intensity)&&q.intensity>=0&&Finite(q.height)&&q.height>=0&&Finite(q.range)&&q.range>0&&Finite(q.decay)&&q.decay>0,"point light format "+a.id+" "+JsonUtility.ToJson(q));Floats(a.light,3);Check(q.color==(int)a.light[0]&&Mathf.Abs(q.intensity-a.light[1])<.000001f&&Mathf.Abs(q.height-a.light[2])<.000001f,"point light metadata");}}foreach(var id in Ids)Check(found.Contains(id),"missing core identity");ChestPresentationBuilder.Validate(d);ChestSurfaceBuilder.Validate(d);return d;}
 public static Mesh MeshOf(float[] p,float[] normal,float[] color,int[] ix,float[] glow=null){int n=p.Length/3;Floats(p,n*3);Floats(normal,n*3);Floats(color,n*3);var v=new Vector3[n];var nn=new Vector3[n];var cc=new Color[n];var gg=new List<Vector2>(n);for(int k=0;k<n;k++){v[k]=new Vector3(p[k*3],p[k*3+1],p[k*3+2]);nn[k]=new Vector3(normal[k*3],normal[k*3+1],normal[k*3+2]);cc[k]=new Color(color[k*3],color[k*3+1],color[k*3+2],1);gg.Add(new Vector2(glow==null?0:glow[k],0));}var m=new Mesh{indexFormat=n>65535?IndexFormat.UInt32:IndexFormat.UInt16,vertices=v,normals=nn,colors=cc,uv=new Vector2[n],triangles=ix};m.SetUVs(2,gg);m.RecalculateBounds();return m;}
 static void Collider(GameObject o,Asset a,Mesh source){if(a.radius<=0)return;var c=o.AddComponent<MeshCollider>();if(a.shape){c.sharedMesh=source;return;}if(a.circleColliders!=null){const int CircleSteps=24;var cv=new List<Vector3>();var ci=new List<int>();foreach(var q in a.circleColliders){int first=cv.Count;var center=V(q.center);for(int layer=0;layer<2;layer++)for(int j=0;j<CircleSteps;j++){float angle=j*Mathf.PI*2/CircleSteps;cv.Add(center+new Vector3(Mathf.Cos(angle)*q.radius,layer*q.height,Mathf.Sin(angle)*q.radius));}cv.Add(center);cv.Add(center+Vector3.up*q.height);for(int j=0;j<CircleSteps;j++){int k=(j+1)%CircleSteps;ci.AddRange(new[]{first+j,first+j+CircleSteps,first+k,first+k,first+j+CircleSteps,first+k+CircleSteps,first+2*CircleSteps,first+k,first+j,first+2*CircleSteps+1,first+j+CircleSteps,first+k+CircleSteps});}}var circleMesh=new Mesh{name=a.id+"-circle-proxies",vertices=cv.ToArray(),triangles=ci.ToArray()};circleMesh.RecalculateBounds();c.sharedMesh=SharedImportCache.StoreMesh(circleMesh,"small-circle-proxies/1\n"+JsonUtility.ToJson(a));return;}const int N=24;var v=new List<Vector3>();for(int y=0;y<2;y++)for(int j=0;j<N;j++){float t=j*Mathf.PI*2/N;v.Add(new Vector3(Mathf.Cos(t)*a.radius,y*a.height,Mathf.Sin(t)*a.radius));}v.Add(Vector3.zero);v.Add(Vector3.up*a.height);var ix=new List<int>();for(int j=0;j<N;j++){int k=(j+1)%N;ix.AddRange(new[]{j,j+N,k,k,j+N,k+N,2*N,k,j,2*N+1,j+N,k+N});}var mesh=new Mesh{name=a.id+"-circle-proxy",vertices=v.ToArray(),triangles=ix.ToArray()};mesh.RecalculateBounds();c.sharedMesh=SharedImportCache.StoreMesh(mesh,"small-circle-proxy/1\n"+JsonUtility.ToJson(new CircleProxy{center=new[]{0f,0f,0f},radius=a.radius,height=a.height}));}
 public static int Build(string directory,string assetDirectory,Transform parent,Shader shader,Dictionary<string,GameObject> prefabs){return Build(directory,assetDirectory,parent,shader,prefabs,null);}
 public static int Build(string directory,string assetDirectory,Transform parent,Shader shader,Dictionary<string,GameObject> prefabs,IReadOnlyDictionary<string,GameObject> externalPrefabs){return FibrePrefabImport.Build(directory,assetDirectory,parent,shader,prefabs,externalPrefabs,BuildNative);}
 static int BuildNative(string directory,string assetDirectory,Transform parent,Shader shader,Dictionary<string,GameObject> prefabs){string file=Path.Combine(directory,"small_props.json");if(!File.Exists(file))return 0;var data=Read(file);Check(data.atlas!=null&&data.atlas.colorSpace=="sRGB"&&data.atlas.width>0&&data.atlas.width<=1024&&data.atlas.height>0&&data.atlas.height<=1024,"atlas contract");var atlas=SharedImportCache.Image(Convert.FromBase64String(data.atlas.png),".png",true,true,TextureWrapMode.Clamp,FilterMode.Trilinear,2,2048);Check(atlas.width==data.atlas.width&&atlas.height==data.atlas.height,"atlas size");var presentation=new ChestPresentationBuilder(data,assetDirectory);var chestSurface=new ChestSurfaceBuilder(data);var assets=new Dictionary<string,Asset>();var mats=new Dictionary<string,Material>();var surfaceTextures=new Dictionary<string,Texture2D>();
  foreach(var a in data.assets){assets.Add(a.id,a);string key=a.material+chestSurface.Key(a.id)+((a.id=="tiedsack"||a.id=="coiledrope")?"-fibre-"+a.id:"")+(a.id=="treasurechest_rainbow"?"-rainbow":"")+(Array.Exists(a.glow,g=>g>0)?"-glow":"")+(a.surface==null?"":"-"+a.surface.id)+(a.id=="lantern"?"-shadow-bias":"");if(a.surface!=null&&!surfaceTextures.ContainsKey(a.surface.id)){var tx=SharedImportCache.Image(Convert.FromBase64String(a.surface.png),".png",true,true,a.id=="seafan"?TextureWrapMode.Clamp:TextureWrapMode.Repeat,FilterMode.Trilinear,2,a.id=="seafan"?256:128);Check(tx.width==(a.id=="seafan"?256:128)&&tx.height==(a.id=="seafan"?256:128),"surface image size");surfaceTextures.Add(a.surface.id,tx);}if(!mats.ContainsKey(key)){var selected=(a.id=="tiedsack"||a.id=="coiledrope")?Shader.Find("MapSharedProps/FibreProp"):a.material=="chestmetal"?Shader.Find("MapSharedProps/ChestMetal"):shader;selected=chestSurface.ShaderFor(a.id,selected);Check(selected!=null&&selected.isSupported,"supported small prop shader "+a.id);var mat=new Material(selected){name="small-props-"+key};if(a.material=="chestmetal"){mat.SetFloat("_Rainbow",a.id=="treasurechest_rainbow"?1:0);mat.SetFloat("_ChestTime",-1);}if(a.id=="tiedsack"||a.id=="coiledrope")mat.SetFloat("_FibreKind",a.id=="coiledrope"?1:0);mat.SetTexture("_BaseMap",a.surface!=null?surfaceTextures[a.surface.id]:a.material=="cards2"?atlas:Texture2D.whiteTexture);mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Cutoff",a.material=="cards2"||(a.id=="seafan"&&a.surface!=null)?.42f:0);mat.SetFloat("_Cull",2);if(Array.Exists(a.glow,g=>g>0))mat.EnableKeyword("SHARED_GLOW");if(a.id=="lantern")mat.EnableKeyword("SMALL_PROP_SHADOW_BIAS");chestSurface.Configure(mat,a.id);AssetDatabase.CreateAsset(mat,assetDirectory+"/small-"+key+".mat");mats.Add(key,mat);}var mesh=MeshOf(a.positions,a.normals,a.colors,a.triangles,a.glow);var uv=new Vector2[a.uv.Length/2];for(int k=0;k<uv.Length;k++)uv[k]=new Vector2(a.uv[k*2],(a.material=="cards2"||a.surface!=null)?1-a.uv[k*2+1]:a.uv[k*2+1]);mesh.uv=uv;mesh.name=a.id;mesh=SharedImportCache.StoreMesh(mesh,"small/1\n"+JsonUtility.ToJson(a));var o=new GameObject(a.id);o.AddComponent<MeshFilter>().sharedMesh=chestSurface.WornVisual(a.id,mesh);var r=o.AddComponent<MeshRenderer>();r.sharedMaterial=mats[key];r.shadowCastingMode=ShadowCastingMode.On;r.receiveShadows=true;Collider(o,a,mesh);if(a.light!=null&&a.light.Length==3){var light=new GameObject("Light").AddComponent<Light>();light.transform.SetParent(o.transform,false);light.transform.localPosition=new Vector3(0,a.pointLight!=null?a.pointLight.height+a.groundSink:a.height*.9f,0);light.type=LightType.Point;int color=a.pointLight!=null?a.pointLight.color:(int)a.light[0];light.color=new Color32((byte)(color>>16),(byte)(color>>8),(byte)color,255);light.intensity=a.pointLight!=null?a.pointLight.intensity:a.light[1];light.range=a.pointLight!=null?a.pointLight.range:a.light[2];light.shadows=LightShadows.None;}presentation.Attach(o,a.id);chestSurface.ApplyRoyalLit(o,a.id,assetDirectory);var path=assetDirectory+"/small-"+a.id+".prefab";prefabs.Add(a.id,PrefabUtility.SaveAsPrefabAsset(o,path));UnityEngine.Object.DestroyImmediate(o);}
  var ground=new Dictionary<string,GroundedPropsV1.Instance>();if(data.grounded!=null&&data.grounded.instances!=null)foreach(var g in data.grounded.instances){Check(g!=null&&(Ids.Contains(g.type)||AdditionalIds.Contains(g.type))&&!ground.ContainsKey(g.instanceId),"ground identity");ground.Add(g.instanceId,g);}
  var roots=new Dictionary<string,float[]>();var tints=new Dictionary<string,float[]>();if(data.instances!=null)foreach(var t in data.instances){Floats(t.tint,3);Check(!tints.ContainsKey(t.instanceId),"duplicate tint");tints.Add(t.instanceId,t.tint);if(t.rootPosition!=null&&t.rootPosition.Length>0){Floats(t.rootPosition,3);roots.Add(t.instanceId,t.rootPosition);}}
  int placed=0;foreach(string line in File.ReadAllLines(Path.Combine(directory,"props.csv"))){var row=line.Split(',');if(row.Length!=11||!assets.TryGetValue(row[1],out var a))continue;Check(row[2]==a.assetKey,"CSV asset key");var o=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[a.id],parent);o.name=row[0];var fx=o.GetComponent<ChestPresentation>();if(fx!=null)fx.SetSeed(row[0]);o.transform.localPosition=new Vector3(Number(row[3]),Number(row[4]),Number(row[5]));if(roots.TryGetValue(row[0],out var sourceRoot)){Check(a.id=="rowboat"||ExtraIds.Contains(a.id)||ExtraV2Ids.Contains(a.id),"root override scope");o.transform.localPosition=V(sourceRoot);}o.transform.localRotation=Quaternion.Euler(0,Number(row[6]),0);o.transform.localScale=new Vector3(Number(row[7]),Number(row[8]),Number(row[7]));Check(o.transform.localScale.x>0&&o.transform.localScale.y>0,"scale");if(a.pointLight!=null){var light=o.GetComponentInChildren<Light>();light.transform.localPosition=new Vector3(0,(a.pointLight.height*o.transform.localScale.x+a.groundSink)/o.transform.localScale.y,0);light.intensity=a.pointLight.intensity*o.transform.localScale.x;light.range=a.pointLight.range;}
   if(ground.TryGetValue(row[0],out var pose)){Check(a.parts!=null&&pose.parts!=null&&a.parts.Length==pose.parts.Length,"ground parts");for(int k=0;k<3;k++)Check(Mathf.Abs(o.transform.localPosition[k]-pose.source.position[k])<.0011f,"ground source position");Check(Mathf.Abs(Number(row[6])-pose.source.yaw)<.011f,"ground source rotation");var pieces=new CombineInstance[a.parts.Length];var temporary=new List<Mesh>();for(int k=0;k<a.parts.Length;k++){var part=a.parts[k];var tr=Array.Find(pose.parts,p=>p.id==part.id);Check(tr!=null,"ground part identity");Floats(tr.rotation,4);var mesh=MeshOf(part.positions,part.normals,part.colors,part.triangles);temporary.Add(mesh);pieces[k]=new CombineInstance{mesh=mesh,transform=Matrix4x4.TRS(o.transform.localPosition,o.transform.localRotation,o.transform.localScale).inverse*Matrix4x4.TRS(V(tr.position),new Quaternion(tr.rotation[0],tr.rotation[1],tr.rotation[2],tr.rotation[3]),V(tr.scale))};}var combined=new Mesh{name=a.id+"-grounded"};combined.CombineMeshes(pieces,true,true);if(a.id=="coiledrope"){Check(combined.vertexCount==a.uv.Length/2,"rope finish UV vertex order");var fibreUv=new Vector2[combined.vertexCount];for(int k=0;k<fibreUv.Length;k++)fibreUv[k]=new Vector2(a.uv[k*2],a.uv[k*2+1]);combined.uv=fibreUv;}combined.RecalculateBounds();AssetDatabase.CreateAsset(combined,assetDirectory+"/small-grounded-"+placed.ToString("D4")+".asset");o.GetComponent<MeshFilter>().sharedMesh=combined;foreach(var mesh in temporary)UnityEngine.Object.DestroyImmediate(mesh);}
   if(tints.TryGetValue(row[0],out var tint)){var block=new MaterialPropertyBlock();block.SetColor("_BaseColor",new Color(tint[0],tint[1],tint[2],1));var renderer=o.GetComponent<Renderer>();renderer.SetPropertyBlock(block);if(chestSurface.HasRoyal(a.id)){var assigned=renderer.sharedMaterials;for(int mi=0;mi<assigned.Length;mi++){var item=new MaterialPropertyBlock();item.SetColor("_BaseColor",assigned[mi].shader.name=="Universal Render Pipeline/Lit"?ChestRoyalLitBuilder.Gold*new Color(tint[0],tint[1],tint[2],1):new Color(tint[0],tint[1],tint[2],1));renderer.SetPropertyBlock(item,mi);}}}
   placed++;
  }return placed;
 }
